<?php foreach($volunteers as $v):$legacy=empty($v['user_id']);$edit=e(json_encode(['id'=>$v['id'],'full_name'=>$v['full_name'],'email'=>$v['email'],'mobile'=>$v['mobile'],'gender'=>$v['gender'],'date_of_birth'=>$v['date_of_birth'],'address'=>$v['address'],'city'=>$v['city'],'country'=>$v['country'],'skills'=>$v['skills'],'occupation'=>$v['occupation'],'interests'=>$v['interests'],'emergency_contact'=>$v['emergency_contact']],JSON_HEX_APOS|JSON_HEX_QUOT));?><tr><td><div class="table-person"><?php $logo=setting('foundation','logo_path','');$logoEnabled=setting('foundation','logo_enabled','1')==='1'; if($v['profile_photo']):?><img src="<?=e(public_upload($v['profile_photo']))?>" alt=""><?php elseif($logoEnabled&&$logo):?><span class="brand-avatar-fallback"><img src="<?=e(public_upload($logo))?>" alt="Foundation logo"></span><?php else:?><span><?=e(strtoupper(substr($v['full_name'],0,1)))?></span><?php endif;?><div><b><?=e($v['full_name'])?></b><small><?=e($v['occupation']?:'Volunteer applicant')?></small><?php if($legacy):?><em class="legacy-badge">Legacy application</em><?php endif;?></div></div></td><td><?=e($v['email'])?><small><?=e($v['mobile'])?></small></td><td><code><?=e($v['volunteer_id']?:'Generated on approval')?></code></td><td><span class="status-badge <?=e($v['status'])?>"><?=e(ucfirst($v['status']))?></span><small>Portal: <?=e($v['user_status']??($legacy?'not created':'n/a'))?></small></td><td><?=e(date('d M Y',strtotime($v['created_at'])))?></td><td><div class="inline-actions volunteer-actions"><button class="outline-link mini" type="button" data-volunteer-edit='<?=$edit?>'>✎ Edit</button>
<?php if($v['status']==='pending'):?>
<form method="post" action="<?=url('admin/volunteers/status')?>" class="volunteer-approve-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="active"><?php if($legacy):?><label><span>Portal Password</span><input type="password" name="portal_password" minlength="10" required placeholder="Minimum 10 characters" autocomplete="new-password"><small>Required once for this older application.</small></label><?php endif;?><button class="approve">✓ Approve & Activate Portal</button></form>
<form method="post" action="<?=url('admin/volunteers/status')?>" data-confirm="Reject this volunteer application?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="rejected"><button class="reject">× Reject</button></form>
<?php elseif(in_array($v['status'],['approved','active'],true)):?>
<form method="post" action="<?=url('admin/volunteers/status')?>" data-confirm="Suspend this volunteer and portal access?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="suspended"><button class="reject">Suspend</button></form>
<?php else:?>
<form method="post" action="<?=url('admin/volunteers/status')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="active"><?php if($legacy):?><label><span>Portal Password</span><input type="password" name="portal_password" minlength="10" required placeholder="Minimum 10 characters" autocomplete="new-password"></label><?php endif;?><button class="approve">Reactivate</button></form>
<?php endif;?>
<?php if($v['verification_token']):?><a class="outline-link mini" href="<?=url('verify/volunteer/'.$v['verification_token'])?>" target="_blank">Verify ↗</a><?php endif;?><?php if($user['role']==='super_admin'):?><form method="post" action="<?=url('admin/volunteers/delete')?>" data-confirm="Permanently delete this volunteer and linked portal account?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$v['id']?>"><button class="danger-link">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?>
